insert into public.lec_pda (code, campo, disciplina, contenido_code, contenido_text, grade, text, position) values
  ('L.E.C1.G1', 'Lenguajes', 'Español', 'L.E.C1', 'La diversidad de lenguas y su uso en la comunicación familiar, escolar y comunitaria', 1, 'Reconoce la riqueza lingüística de México y el mundo, a partir de obras literarias procedentes de distintas culturas.', 1),
  ('L.E.C1.G2', 'Lenguajes', 'Español', 'L.E.C1', 'La diversidad de lenguas y su uso en la comunicación familiar, escolar y comunitaria', 2, 'Comprende las características y recursos lingüísticos de la lengua española, para usarlos y valorarlos como parte de la riqueza pluricultural de México y del mundo.', 2),
  ('L.E.C1.G3', 'Lenguajes', 'Español', 'L.E.C1', 'La diversidad de lenguas y su uso en la comunicación familiar, escolar y comunitaria', 3, 'Analiza y reconoce algunas variantes lingüísticas de la lengua española, para valorarla como riqueza cultural.', 3),
  ('L.E.C2.G1', 'Lenguajes', 'Español', 'L.E.C2', 'La diversidad étnica, cultural y lingüística de México a favor de una sociedad intercultural.', 1, 'Comprende las ideas centrales y secundarias de textos relacionados con la diversidad étnica, cultural y lingüística, que favorecen una sociedad intercultural, para comentarlas en forma oral y escrita.', 4),
  ('L.E.C2.G2', 'Lenguajes', 'Español', 'L.E.C2', 'La diversidad étnica, cultural y lingüística de México a favor de una sociedad intercultural.', 2, 'Compara y contrasta textos sobre las tensiones y conflictos en las sociedades contemporáneas y manifiesta, de manera oral o escrita, la necesidad de practicar la comunicación asertiva.', 5),
  ('L.E.C2.G3', 'Lenguajes', 'Español', 'L.E.C2', 'La diversidad étnica, cultural y lingüística de México a favor de una sociedad intercultural.', 3, 'Practica la comunicación asertiva y el diálogo intercultural en interacción con otras personas.', 6),
  ('L.E.C2.G2.b', 'Lenguajes', 'Español', 'L.E.C2', 'La diversidad étnica, cultural y lingüística de México a favor de una sociedad intercultural.', 2, 'Analiza textos sobre las sociedades multiculturales y expresa la función que tiene el diálogo intercultural para la construcción democrática y la interacción en sociedad.', 7),
  ('L.E.C2.G3.b', 'Lenguajes', 'Español', 'L.E.C2', 'La diversidad étnica, cultural y lingüística de México a favor de una sociedad intercultural.', 3, 'Comparte una propuesta creativa propia en la que valore y promueva textos en español a favor de una sociedad intercultural.', 8),
  ('L.E.C3.G1', 'Lenguajes', 'Español', 'L.E.C3', 'Las lenguas como manifestación de la identidad y del sentido de pertenencia.', 1, 'Describe un texto cómo el lenguaje oral manifiesta las identidades personal y colectiva, para reconocer lo común y lo diferente.', 9),
  ('L.E.C3.G2', 'Lenguajes', 'Español', 'L.E.C3', 'Las lenguas como manifestación de la identidad y del sentido de pertenencia.', 2, 'Comprende y redacta textos narrativos sobre la construcción de la identidad y el sentido de pertenencia, a partir del análisis de variantes del español.', 10),
  ('L.E.C3.G3', 'Lenguajes', 'Español', 'L.E.C3', 'Las lenguas como manifestación de la identidad y del sentido de pertenencia.', 3, 'Elabora textos argumentativos acerca de la interculturalidad crítica, para reconocer el valor de las lenguas, a fin de promoverlas y fortalecerlas.', 11),
  ('L.E.C4.G1', 'Lenguajes', 'Español', 'L.E.C4', 'El dinamismo de las lenguas y su relevancia como patromonio cultural.', 1, 'Identifica y expresa la relevancia de valorar las lenguas como legado de la comunidad.', 12),
  ('L.E.C4.G2', 'Lenguajes', 'Español', 'L.E.C4', 'El dinamismo de las lenguas y su relevancia como patromonio cultural.', 2, 'Reconoce cambios temporales y geográficos del español en la comunidad, el país o el mundo hispano.', 13),
  ('L.E.C4.G3', 'Lenguajes', 'Español', 'L.E.C4', 'El dinamismo de las lenguas y su relevancia como patromonio cultural.', 3, 'Analiza en textos literarios neologismos, juegos de lenguajes, caló, jerga, préstamos lingüísticos y extranjerismos como parte del dinamismo de la lengua española.', 14),
  ('L.E.C5.G1', 'Lenguajes', 'Español', 'L.E.C5', 'La función creativa del español en la expresión de necesidades e intereses comunitarios.', 1, 'Identifica una situación problemática de la comundiad, haciendo uso del pensamiento crítico, para plantear diversas formas creativas de resolverla, por ejemplo, con un cuento.', 15),
  ('L.E.C5.G2', 'Lenguajes', 'Español', 'L.E.C5', 'La función creativa del español en la expresión de necesidades e intereses comunitarios.', 2, 'Expresa mediante un esnayo, una postura crítica sobre necesidades, intereses y problemas de la comunidad.', 16),
  ('L.E.C5.G3', 'Lenguajes', 'Español', 'L.E.C5', 'La función creativa del español en la expresión de necesidades e intereses comunitarios.', 3, 'Crea textos literarios de distintos géneros para ofrecer una propuesta de solución a problemas de la comunidad.', 17),
  ('L.E.C6.G1', 'Lenguajes', 'Español', 'L.E.C6', 'Los elementos y los recursos estéticos de la lengua española en la literatura oral y escrita.', 1, 'Reconoce los recursos estéticos en textos literarios líricos, orales y escritos, y disfruta de poemas, canciones y juegos de palabras, entre otros.', 18),
  ('L.E.C6.G2', 'Lenguajes', 'Español', 'L.E.C6', 'Los elementos y los recursos estéticos de la lengua española en la literatura oral y escrita.', 2, 'Analiza las características y recursos estéticos de los textos narrativos, e interpreta y disfruta de cuentos y novelas.', 19),
  ('L.E.C6.G3', 'Lenguajes', 'Español', 'L.E.C6', 'Los elementos y los recursos estéticos de la lengua española en la literatura oral y escrita.', 3, 'Usa creativa e intencionalmente las características y los recursos estéticos de textos dramáticos, para escenificar situaciones vinculadas con la comunidad.', 20),
  ('L.E.C7.G1', 'Lenguajes', 'Español', 'L.E.C7', 'Textos literario escritos en español o traducidos.', 1, 'Reconoce el valor estético de diversos géneros literarios de su elección, para elaborar comentarios y promover su lectura.', 21),
  ('L.E.C7.G2', 'Lenguajes', 'Español', 'L.E.C7', 'Textos literario escritos en español o traducidos.', 2, 'Analiza diversos textos literarios de su elección para expresar un juicio estético y lo comparte en la comunidad.', 22),
  ('L.E.C7.G3', 'Lenguajes', 'Español', 'L.E.C7', 'Textos literario escritos en español o traducidos.', 3, 'Elabora un ensayo acerca del tratamiento de un tema de su elección, con base en algún género literario de su preferencia, para argumentar un juicio estético sobre éste.', 23),
  ('L.E.C8.G1', 'Lenguajes', 'Español', 'L.E.C8', 'Creeaciones literarias tradicionales y contemporáneas.', 1, 'Recupera y clasifica creaciones literarias de la comunidad o de un lugar de interés, como mitos, leyendas, fábulas, epopeyas, cantares de gesta, refranes, coplas, canciones, corridos y juegos de palabras, para promover de manera creativa su lectura.', 24),
  ('L.E.C8.G2', 'Lenguajes', 'Español', 'L.E.C8', 'Creeaciones literarias tradicionales y contemporáneas.', 2, 'Valora textos literarios tradicionales y contemporáneos, como cuentos, novelas, poemas y textos dramáticos; los adapta a otros lenguajes para sensabilizar a la comunidad acerca de la relevancia social y cultura de la literatura.', 25),
  ('L.E.C8.G3', 'Lenguajes', 'Español', 'L.E.C8', 'Creeaciones literarias tradicionales y contemporáneas.', 3, 'Crea textos narrativos poéticos, dramáticos y guiones para audiovisuales, entre otros, a partir del uso de recursos literarios, para exponer una situación real o ficticia.', 26),
  ('L.E.C9.G1', 'Lenguajes', 'Español', 'L.E.C9', 'Recursos literarios en lengua española para expresar sensaciones, emociones, sentimientos e ideas vinculados con las familias, la escuela y la comunidad.', 1, 'Identifica recursos literarios en lengua española y los emplea en la elaboración de cartas personales y biografías, para expresar sensaciones, emociones, sentimientos e ideas que experimenta en su entorno familiar, escolar o comunitario.', 27),
  ('L.E.C9.G2', 'Lenguajes', 'Español', 'L.E.C9', 'Recursos literarios en lengua española para expresar sensaciones, emociones, sentimientos e ideas vinculados con las familias, la escuela y la comunidad.', 2, 'Analiza recursos literarios en lengua española para expresar sensaciones, emociones, sentimientos e ideas al elaborar una autobiografía con respecto a los vínculos consigo mismo y con el entorno familiar, escolar o comunitario.', 28),
  ('L.E.C9.G3', 'Lenguajes', 'Español', 'L.E.C9', 'Recursos literarios en lengua española para expresar sensaciones, emociones, sentimientos e ideas vinculados con las familias, la escuela y la comunidad.', 3, 'Recupera recursos literarios de la lengua española para crear un texto libre que describa los vínculos con el entorno familiar, escolar o comunitario.', 29),
  ('L.E.C10.G1', 'Lenguajes', 'Español', 'L.E.C10', 'Los géneros periodísticos y sus recursos para comunicar sucesos significativos familiares, escolares, comunitarios y sociales.', 1, 'Identifica sucesos significativos familiares, escolares, comunitarios y sociales que forman parte de la memoria colectiva y los comunica haciendo uso de las carcaterísticas de los géneros periodísticos informativos.', 30),
  ('L.E.C10.G2', 'Lenguajes', 'Español', 'L.E.C10', 'Los géneros periodísticos y sus recursos para comunicar sucesos significativos familiares, escolares, comunitarios y sociales.', 2, 'Investiga un evento familiar, escolar o comunitario significativo de la memoria colectiva, para comunicarlo utilizando las características de los géneros periodísticos de opinión.', 31),
  ('L.E.C10.G3', 'Lenguajes', 'Español', 'L.E.C10', 'Los géneros periodísticos y sus recursos para comunicar sucesos significativos familiares, escolares, comunitarios y sociales.', 3, 'Analiza los sucesos más significativos de la comunidad y los comunica empleando las características de los géneros periodísticos de interpretación, para preservar la memoria colectiva.', 32),
  ('L.E.C11.G1', 'Lenguajes', 'Español', 'L.E.C11', 'Comunicación asertvica y dialógica para erradicar expresiones de violencia.', 1, 'Realiza, de manera colectiva, una propuesta oral o escrito, para promover acciones que posibiletn erradicar la violencia en las familias y la escuela.', 33),
  ('L.E.C11.G2', 'Lenguajes', 'Español', 'L.E.C11', 'Comunicación asertvica y dialógica para erradicar expresiones de violencia.', 2, 'Participa en un debate acerca de algunas expresiones de violencia \- como la de género y la sexual- para argumentar una postura de rechazo.', 34),
  ('L.E.C11.G3', 'Lenguajes', 'Español', 'L.E.C11', 'Comunicación asertvica y dialógica para erradicar expresiones de violencia.', 3, 'Discute de forma colectiva y diseña una estrategia sobre la importancia de sensibilizar a la comunidad acerca de la violencia.', 35),
  ('L.E.C12.G1', 'Lenguajes', 'Español', 'L.E.C12', 'Comunicación asertvica y dialógica para erradicar expresiones de violencia.', 1, 'Elabora solicitudes de gestión de espacios y recursos para dar a conocer la propuesta.', 36),
  ('L.E.C12.G2', 'Lenguajes', 'Español', 'L.E.C12', 'Comunicación asertvica y dialógica para erradicar expresiones de violencia.', 2, 'Elabora invitaciones a expertos y redacta oficios de gestión para obtener recursos y espacios donde tendrá lugar el encuentro.', 37),
  ('L.E.C12.G3', 'Lenguajes', 'Español', 'L.E.C12', 'Comunicación asertvica y dialógica para erradicar expresiones de violencia.', 3, 'Redacta un texto informativo acerca de la importancia de erradicar la violencia y realiza de manera formal las gestiones necesarias para compartirlo con la comunidad.', 38),
  ('L.E.C13.G1', 'Lenguajes', 'Español', 'L.E.C13', 'Mensajes para promover una vida saludable, expresados en medios comunitarios o masivos de comunicación.', 1, 'Identifica las características y recursos de mensajes que promueven una vida saludable a través de los diferentes medios comunitarios o masivos de comunicación impresos o audiovisuales.', 39),
  ('L.E.C13.G2', 'Lenguajes', 'Español', 'L.E.C13', 'Mensajes para promover una vida saludable, expresados en medios comunitarios o masivos de comunicación.', 2, 'Elabora un mensaje impreso empleando imágenes, textos, colores y otros recursos gráficos, para favorecer una vida saludable, y lo comparte en la comunidad.', 40),
  ('L.E.C13.G3', 'Lenguajes', 'Español', 'L.E.C13', 'Mensajes para promover una vida saludable, expresados en medios comunitarios o masivos de comunicación.', 3, 'Construye narrativas acerca de una vida saludable, haciendo uso del lenguaje audiovisual y las transmite por medios comunitarios o masivos de comunicación.', 41),
  ('L.E.C14.G1', 'Lenguajes', 'Español', 'L.E.C14', 'Texto de divulgación científica.', 1, 'Identifica las características del texto de divulgación científica y elabora uno.', 42),
  ('L.E.C14.G2', 'Lenguajes', 'Español', 'L.E.C14', 'Texto de divulgación científica.', 2, 'Analiza las características del texto de divulgación científica, para elaborar y dar a conocer diversos textos científicos orales o escritos que traten sobre un tema de interés personal o colectivo.', 43),
  ('L.E.C14.G3', 'Lenguajes', 'Español', 'L.E.C14', 'Texto de divulgación científica.', 3, 'Elabora una propuesta de divulgación científica, con la participación de la comunidad escolar, para fomentar el conocimiento de las ciencias.', 44),
  ('L.E.C15.G1', 'Lenguajes', 'Español', 'L.E.C15', 'Manifestaciones culturales y artísticas que favorecen una sociedad incluyente.', 1, 'Reconoce manifestaciones culturales y artísticas creadas o ejecutadas por personas con alguna discapacidad, para distinguir sus valores estéticos y creativos y las comparte en forma oral o escrita con la comunidad.', 45),
  ('L.E.C15.G2', 'Lenguajes', 'Español', 'L.E.C15', 'Manifestaciones culturales y artísticas que favorecen una sociedad incluyente.', 2, 'Elabora un texto oral o escrito acerca de las manifestaciones culturales y artísticas que promuevan una sociedad incluyente.', 46),
  ('L.E.C15.G3', 'Lenguajes', 'Español', 'L.E.C15', 'Manifestaciones culturales y artísticas que favorecen una sociedad incluyente.', 3, 'Crea un texto literario que aborde un tema que promueva una sociedad incluyente.', 47),
  ('L.I.C1.G1', 'Lenguajes', 'Inglés', 'L.I.C1', 'La diversidad lingüística y sus formas de expresión en México y el mundo.', 1, 'Hace uso del alfabeto, los números y las expresiones básicas en inglés, para nombrar y recuperar datos factuales y características básicas de lenguas reconocidas en México y el mundo.', 48),
  ('L.I.C1.G2', 'Lenguajes', 'Inglés', 'L.I.C1', 'La diversidad lingüística y sus formas de expresión en México y el mundo.', 2, 'Comprende textos narrativos y biográficos en inglés sobre la vida cotidiana, formas de interacción y comportamiento de hablantes de diversas lenguas de México y el mundo en el pasado, y lo expresa en organizadores gráficos, infografías u otras formas de presentación escrita y oral.', 49),
  ('L.I.C1.G3', 'Lenguajes', 'Inglés', 'L.I.C1', 'La diversidad lingüística y sus formas de expresión en México y el mundo.', 3, 'Utiliza diversos tipos de texto y medios de comunicación para expresar y difundir en inglés prácticas culturales y lingüísticas diversas de sociedades en México y el mundo.', 50),
  ('L.I.C2.G1', 'Lenguajes', 'Inglés', 'L.I.C2', 'La identidad y cultura de pueblos de habla inglesa.', 1, 'Recupera información para llevar a cabo presentaciones en inglés, orales y escritas, que describan rasgos étnicos, culturales e identitatios de hablantes de lengua inglesa.', 51),
  ('L.I.C2.G2', 'Lenguajes', 'Inglés', 'L.I.C2', 'La identidad y cultura de pueblos de habla inglesa.', 2, 'Elabora fichas informativas en inglés sobre rasgos identitatios de pueblos de habla inglesa (acento, grafía, vestimenta, comida, tradiciones, costumbres, entre otros).', 52),
  ('L.I.C2.G3', 'Lenguajes', 'Inglés', 'L.I.C2', 'La identidad y cultura de pueblos de habla inglesa.', 3, 'Construye una propuesta de comunicación en inglés, oral y escrita, donde contraste, valore y promueva rasgos de una sociedad intercultural identificados en pueblos de habla inglesa.', 53),
  ('L.I.C3.G1', 'Lenguajes', 'Inglés', 'L.I.C3', 'Las manifestaciones culturales, lingüísticas y artísticas en inglés, a favor de la interculturalidad.', 1, 'Elabora un cómic o manga en inglés sobre situaciones donde se rescata la importancia de la interculturalidad.', 54),
  ('L.I.C3.G2', 'Lenguajes', 'Inglés', 'L.I.C3', 'Las manifestaciones culturales, lingüísticas y artísticas en inglés, a favor de la interculturalidad.', 2, 'Interpreta juegos de roles en inglés sobre situaciones que favorezcan la comunicación asertiva.', 55),
  ('L.I.C3.G3', 'Lenguajes', 'Inglés', 'L.I.C3', 'Las manifestaciones culturales, lingüísticas y artísticas en inglés, a favor de la interculturalidad.', 3, 'Elabora guiones en inglés que aborden situaciones de conflicto resueltas mediante la comunicación asertiva e intercultural, y los dramatiza.', 56),
  ('L.I.C4.G1', 'Lenguajes', 'Inglés', 'L.I.C4', 'Uso de diversos textos en inglés que promuevem la preservación y conservación de las lenguas.', 1, 'Recupera estrategias acerca de la conservación y preservación de las lenguas, planteadas en textos informativos y científicos en inglés, y las difunde.', 57),
  ('L.I.C4.G2', 'Lenguajes', 'Inglés', 'L.I.C4', 'Uso de diversos textos en inglés que promuevem la preservación y conservación de las lenguas.', 2, 'Indaga y construye propuestas en inglés para concervar y preservar las lenguas como legado y sentido de pertenencia, y las difunde por algún medio de comunicación.', 58),
  ('L.I.C4.G3', 'Lenguajes', 'Inglés', 'L.I.C4', 'Uso de diversos textos en inglés que promuevem la preservación y conservación de las lenguas.', 3, 'Participa en un debate en inglés sobre los cambios lingüísticos y culturales de las lenguas en el transcurso del tiempo, y su impacto en la conformación de nuevas prácticas sociales.', 59),
  ('L.I.C5.G1', 'Lenguajes', 'Inglés', 'L.I.C5', 'El uso del inglés para expresar necesidades, intereses y problemas de la comunidad.', 1, 'Investiga en textos en inglés soluciones implementadas sobre problemas de una comunidad, e informa de manera oral o escrita sus hallazgos.', 60),
  ('L.I.C5.G2', 'Lenguajes', 'Inglés', 'L.I.C5', 'El uso del inglés para expresar necesidades, intereses y problemas de la comunidad.', 2, 'Elabora escritos argumentativos en inglés sobre acciones colectivas que posibiliten la solución de problemas de una comunidad.', 61),
  ('L.I.C5.G3', 'Lenguajes', 'Inglés', 'L.I.C5', 'El uso del inglés para expresar necesidades, intereses y problemas de la comunidad.', 3, 'Organiza una campaña en inglés sobre soluciones a problemas de la comunidad.', 62),
  ('L.I.C6.G1', 'Lenguajes', 'Inglés', 'L.I.C6', 'Elementos y recursos estétivos del inglés.', 1, 'Recupera de distintos tipos de textos literarios en inglés, expresiones, elementos y recursos estéticos y elabora un glosario.', 63),
  ('L.I.C6.G2', 'Lenguajes', 'Inglés', 'L.I.C6', 'Elementos y recursos estétivos del inglés.', 2, 'Identifica y explica el uso de expresiones, elementos y recursos estéticos en manifestaciones culturales y artísticas de países de habla inglesa.', 64),
  ('L.I.C6.G3', 'Lenguajes', 'Inglés', 'L.I.C6', 'Elementos y recursos estétivos del inglés.', 3, 'Emplea algunas figuras retóticas, elementos y recursos estéticos, para construir un texto literario corto, oral y escrito, para difundirlo en la comunidad escolar.', 65),
  ('L.I.C7.G1', 'Lenguajes', 'Inglés', 'L.I.C7', 'Manifestaciones artísticas y culturales del inglés.', 1, 'Realiza una lectura crítica y emite su opinión en inglés sobre diversas manifestaciones culturales y artísticas de pueblos de habla inglesa.', 66),
  ('L.I.C7.G2', 'Lenguajes', 'Inglés', 'L.I.C7', 'Manifestaciones artísticas y culturales del inglés.', 2, 'Selecciona alguna manifestación artística o cultural y la difunde en inglés, mediante elementos y recursos artísticos.', 67),
  ('L.I.C7.G3', 'Lenguajes', 'Inglés', 'L.I.C7', 'Manifestaciones artísticas y culturales del inglés.', 3, 'Crea poemas cortos a partir del uso de recursos estéticos del inglés en producciones orales y escritas, para difundirse en la comundiad escolar.', 68),
  ('L.I.C8.G1', 'Lenguajes', 'Inglés', 'L.I.C8', 'Creaciones literarias tradicionales y contemporáneas en inglés.', 1, 'Seleccione textos literarios en inglés que aborden temas de la comundiad o de algún lugar de interés, los resume y difunde por distintos medios.', 69),
  ('L.I.C8.G2', 'Lenguajes', 'Inglés', 'L.I.C8', 'Creaciones literarias tradicionales y contemporáneas en inglés.', 2, 'Investiga en textos literarios en inglés sobre pueblos indígenas y/o afrodescendientes de México o el mundo.', 70),
  ('L.I.C8.G3', 'Lenguajes', 'Inglés', 'L.I.C8', 'Creaciones literarias tradicionales y contemporáneas en inglés.', 3, 'Crea textos breves en inglés para exponer una situación o tema de interés, con recursos narrativos, poéticos, visuales, escénicos o musicales.', 71),
  ('L.I.C8.G2.b', 'Lenguajes', 'Inglés', 'L.I.C8', 'Creaciones literarias tradicionales y contemporáneas en inglés.', 2, 'Elabora por escrito una apreciación sobre la relevancia y el valor social y cultural de los pueblos indígenas y/o afrodescendientes de México o el mundo.', 72),
  ('L.I.C9.G1', 'Lenguajes', 'Inglés', 'L.I.C9', 'El inglés para expresar sensaciones, emociones, sentimientos e ideas vinculados con las familas, la escuela y la comundiad.', 1, 'Lleva a cabo juegos del lenguaje en inglés para expresar sensaciones, emociones, sentimientos e ideas sobre las familias y la escuela.', 73),
  ('L.I.C9.G2', 'Lenguajes', 'Inglés', 'L.I.C9', 'El inglés para expresar sensaciones, emociones, sentimientos e ideas vinculados con las familas, la escuela y la comundiad.', 2, 'Realiza entrevistas en inglés para recuperar opiniones acerca de emociones, sentimientos e ideas sobre la escuela y la comunidad.', 74),
  ('L.I.C9.G3', 'Lenguajes', 'Inglés', 'L.I.C9', 'El inglés para expresar sensaciones, emociones, sentimientos e ideas vinculados con las familas, la escuela y la comundiad.', 3, 'Investiga y recupera manifestaciones culturales y artísticas de su comunidad, para difundirlas en inglés.', 75),
  ('L.I.C10.G1', 'Lenguajes', 'Inglés', 'L.I.C10', 'Relatos en inglés para expresar sucesos significativos familiares, escolares, comunitarios y sociales.', 1, 'Entrevista y narra en inglés sucesos significativos familiares, escolares, comunitarios o sociales recuperados de la memoria colectiva.', 76),
  ('L.I.C10.G2', 'Lenguajes', 'Inglés', 'L.I.C10', 'Relatos en inglés para expresar sucesos significativos familiares, escolares, comunitarios y sociales.', 2, 'Investiga un acontecimiento familair, escolar o comunitario significativo, recuperado de la memoria colectiva, para redactar una reflexión en inglés.', 77),
  ('L.I.C10.G3', 'Lenguajes', 'Inglés', 'L.I.C10', 'Relatos en inglés para expresar sucesos significativos familiares, escolares, comunitarios y sociales.', 3, 'Recupera un acontecimiento histórico comunitario y elabora un texto oral y escrito en inglés, para expresar su postura, haciendo uso de recursos visuales o auditivos.', 78),
  ('L.I.C11.G1', 'Lenguajes', 'Inglés', 'L.I.C11', 'Comunicación, asertiva y dialógica en inglés para erradicar expresiones de violencia en la familia e la escuela.', 1, 'Recupera de distintos textos en inglés, expresiones de violencia presentes en las familias y las escuelas.', 79),
  ('L.I.C11.G2', 'Lenguajes', 'Inglés', 'L.I.C11', 'Comunicación, asertiva y dialógica en inglés para erradicar expresiones de violencia en la familia e la escuela.', 2, 'Participa en un panel o debate en inglés, sobre la importancia de la comunicación asertiva y dialógica, a fin de consensuar propuestas de acción para sensibilizar sobre la erradicación de la violencia en las familais y la escuela.', 80),
  ('L.I.C11.G3', 'Lenguajes', 'Inglés', 'L.I.C11', 'Comunicación, asertiva y dialógica en inglés para erradicar expresiones de violencia en la familia e la escuela.', 3, 'Diseña y difunde en inglés propuestas escritas para sensibilizar a la comunidad acerca de la importancia de erradicar la violencia.', 81),
  ('L.I.C11.G1.b', 'Lenguajes', 'Inglés', 'L.I.C11', 'Comunicación, asertiva y dialógica en inglés para erradicar expresiones de violencia en la familia e la escuela.', 1, 'Reflexiona y comunica de forma oral y escrita una postura de rechazo a la violencia, mediante la comunicación asertiva y dialógica.', 82),
  ('L.I.C12.G1', 'Lenguajes', 'Inglés', 'L.I.C12', 'Mensajes en inglés en medios de comunicación masiva, que promuevan una vida saludable.', 1, 'Recupera en inglés mensajes que promuevan una vida saludable y los difunde de manera oral o escrita, a través de distintos medios de comunicación.', 83),
  ('L.I.C12.G2', 'Lenguajes', 'Inglés', 'L.I.C12', 'Mensajes en inglés en medios de comunicación masiva, que promuevan una vida saludable.', 2, 'Investiga en diversas fuentes en inglés sobre una vida saludable, para construir un texto informativo y difundirlo a través de medios de comunicación.', 84),
  ('L.I.C12.G3', 'Lenguajes', 'Inglés', 'L.I.C12', 'Mensajes en inglés en medios de comunicación masiva, que promuevan una vida saludable.', 3, 'Cuenta historias en inglés sobre ejemplos de vida saludable y las difunde mediante el uso de medios de comunicación, para sensibilizar a la comunidad.', 85),
  ('L.I.C13.G1', 'Lenguajes', 'Inglés', 'L.I.C13', 'El uso del inglés en la construcción de mensajes a favor de la incllusión.', 1, 'Investiga en diversas fuentes en inglés las características de los mensajes que presentan información a favor de la interacción, sensibilización y empatía con la diversidad y expone su punto de vista.', 86),
  ('L.I.C13.G2', 'Lenguajes', 'Inglés', 'L.I.C13', 'El uso del inglés en la construcción de mensajes a favor de la incllusión.', 2, 'Analiza las características y recursos empleados en la comunicación asertiva en inglés, y sugiere su uso para favorecer una sociedad.', 87),
  ('L.I.C13.G3', 'Lenguajes', 'Inglés', 'L.I.C13', 'El uso del inglés en la construcción de mensajes a favor de la incllusión.', 3, 'Construye un proyecto en inglés para valorar la diversidad y fomentar la inclusión social en su entorno.', 88),
  ('L.I.C14.G1', 'Lenguajes', 'Inglés', 'L.I.C14', 'El uso del inglés en las manifestaciones culturales y artísticas, que favorecen la construcción de una sociedad incluyente.', 1, 'Elabora semblanzas en inglés sobre personas en condición de discapacidad, destacadas por contribuir a la cultura y las artes, y las difunde.', 89),
  ('L.I.C14.G2', 'Lenguajes', 'Inglés', 'L.I.C14', 'El uso del inglés en las manifestaciones culturales y artísticas, que favorecen la construcción de una sociedad incluyente.', 2, 'Investiga, reflexiona y expone en inglés acerca de los sistemas alternativos y aumentativos que favorecen el tránsito a una sociedad incluyente.', 90),
  ('L.I.C14.G3', 'Lenguajes', 'Inglés', 'L.I.C14', 'El uso del inglés en las manifestaciones culturales y artísticas, que favorecen la construcción de una sociedad incluyente.', 3, 'Crea en inglés alguna manifestación artística que aborde cómo los sistemas alternativos aumentativos favorecen sociedades incluyentes.', 91),
  ('L.A.C1.G1', 'Lenguajes', 'Artes', 'L.A.C1', 'Diversidad de lenguajes artísticos en la riqueza pluricultural de México y del mundo.', 1, 'Reconoce en manifestaciones artísticas de México y del mundo el uso del cuerpo, del espacio y del tiempo, para valorarlas como parte de la riqueza pluricultural.', 92),
  ('L.A.C1.G2', 'Lenguajes', 'Artes', 'L.A.C1', 'Diversidad de lenguajes artísticos en la riqueza pluricultural de México y del mundo.', 2, 'Explora la creación de secuencias y patrones al identificar el uso de formas, colores, movimientos y sonidos, entre otros elementos de las artes, en manifestaciones artísticas de México y del mundo, para apreciar la riqueza pluricultural.', 93),
  ('L.A.C1.G3', 'Lenguajes', 'Artes', 'L.A.C1', 'Diversidad de lenguajes artísticos en la riqueza pluricultural de México y del mundo.', 3, 'Experimenta con características de algunos estilos de los lenguajes artísticos, para representar la riqueza pluricultural de México y del mundo.', 94),
  ('L.A.C2.G1', 'Lenguajes', 'Artes', 'L.A.C2', 'Manifestaciones culturales y artísticasque conforman la diversidad étnica, cultural y lingüística.', 1, 'Identifica diferentes manifestaciones culturales y artísticas de pueblos indígenas y afrodescendientes de México y del mundo, para interpretar significados que permitan fomentar una sociedad intercultural.', 95),
  ('L.A.C2.G2', 'Lenguajes', 'Artes', 'L.A.C2', 'Manifestaciones culturales y artísticasque conforman la diversidad étnica, cultural y lingüística.', 2, 'Compara el uso de formas, colomres, movimientos y sonidos, entre otros elementos dde las artes, en manifestaciones culturales y artísticas de diferentes épocas y orígenes culturales, para fomentar una sociedad intercultural.', 96),
  ('L.A.C2.G3', 'Lenguajes', 'Artes', 'L.A.C2', 'Manifestaciones culturales y artísticasque conforman la diversidad étnica, cultural y lingüística.', 3, 'Presenta una propuesta creativa, usando intencionalmente el cuerpo, espacio y tiempo, entre otros elementos de las artes, para valorar y promover la diversidad étnica, cultural y lingüística, a favor de una sociedad intercultural.', 97),
  ('L.A.C3.G1', 'Lenguajes', 'Artes', 'L.A.C3', 'Identidad y sentido de pertenencia en manifestaciones artísticas.', 1, 'Aprecia la intención expresiva en diversas manifestaciones artísticas, para la construcción crítica de las identidades personal y colectiva.', 98),
  ('L.A.C3.G2', 'Lenguajes', 'Artes', 'L.A.C3', 'Identidad y sentido de pertenencia en manifestaciones artísticas.', 2, 'Reflexiona sobre la manera en que las artes fortalecen la identidad, dan sentido de pertenencia y resultan esenciales para favorecer la interculturalidad crítica.', 99),
  ('L.A.C3.G3', 'Lenguajes', 'Artes', 'L.A.C3', 'Identidad y sentido de pertenencia en manifestaciones artísticas.', 3, 'Crea propuestas artísticas utilizando intencionalmente características de algunos estilos artísticos, a favor de la interculturalidad crítica, para fortalecer las identidades personal y colectiva.', 100),
  ('L.A.C4.G1', 'Lenguajes', 'Artes', 'L.A.C4', 'Patrimonio cultural de la comunidad en manifestaciones artísticas que fomentan la identidad y el sentido de pertenencia.', 1, 'Interpreta manifestaciones artísticas del patrominio cultural de la comunidad y de México, para fomentar las identidades personal y colectiva, así como el sentido de pertenencia.', 101),
  ('L.A.C4.G2', 'Lenguajes', 'Artes', 'L.A.C4', 'Patrimonio cultural de la comunidad en manifestaciones artísticas que fomentan la identidad y el sentido de pertenencia.', 2, 'Expresa, mediante lenguajes artísticos, la relevancia de valorar, conservar y preservar el patrimonio cultural, como legado que le otorga identidad y sentido de pertenencia.', 102),
  ('L.A.C4.G3', 'Lenguajes', 'Artes', 'L.A.C4', 'Patrimonio cultural de la comunidad en manifestaciones artísticas que fomentan la identidad y el sentido de pertenencia.', 3, 'Reinterpreta de manera respetuosa manifestaciones artísticas del patrimonio cultural, para valorar su identidad y sentido de pertenencia.', 103),
  ('L.A.C5.G1', 'Lenguajes', 'Artes', 'L.A.C5', 'Los lenguajes artísticos en la expresión de problemas de la comunidad.', 1, 'Usa intencionalmente formas, colores, movimientos y sonidos, entre otros elementos de las artes, para recrear una situación problemática de su contexto y manifestar una postura crítica.', 104),
  ('L.A.C5.G2', 'Lenguajes', 'Artes', 'L.A.C5', 'Los lenguajes artísticos en la expresión de problemas de la comunidad.', 2, 'Investiga propuestas artísticas colectivas de entornos rurales y urbanos a favor de la inclusión, para presentar una postura crítica sobre un problema de la comunidad.', 105),
  ('L.A.C5.G3', 'Lenguajes', 'Artes', 'L.A.C5', 'Los lenguajes artísticos en la expresión de problemas de la comunidad.', 3, 'Experimenta con técnicas artísticas y elige una que implemente en un proyecto escolar creativo, para imaginar y proponer posibles soluciones a problemas de la comunidad.', 106),
  ('L.A.C6.G1', 'Lenguajes', 'Artes', 'L.A.C6', 'Elementos de las artes y recursos estéticos apreciados en el entorno natural y social, así como en diversas manifestaciones artísticas.', 1, 'Identifica el uso intencional del cuerpo, del espacio y del tiempo en manifestaciones artísticas, para apreciar e interpretar sus sentidos y significados.', 107),
  ('L.A.C6.G2', 'Lenguajes', 'Artes', 'L.A.C6', 'Elementos de las artes y recursos estéticos apreciados en el entorno natural y social, así como en diversas manifestaciones artísticas.', 2, 'Analiza el uso intencional de elementos de las artes y recursos estéticos como ritmo, repetición, armonía, contraste y variación, en manifestaciones artísticas, para emplearlos en una creación personal.', 108),
  ('L.A.C6.G3', 'Lenguajes', 'Artes', 'L.A.C6', 'Elementos de las artes y recursos estéticos apreciados en el entorno natural y social, así como en diversas manifestaciones artísticas.', 3, 'Usa intencionalmente figuras retóricas como metáforas, hipérboles, sinécdoques, aliteraciones, en creaciones artísticas colectivas, para representar situaciones vinculadas a la comunidad.', 109),
  ('L.A.C6.G2.b', 'Lenguajes', 'Artes', 'L.A.C6', 'Elementos de las artes y recursos estéticos apreciados en el entorno natural y social, así como en diversas manifestaciones artísticas.', 2, 'Reinterpreta los sentidos y significados de las cualidades estéticas del entorno natural y social en la comundiad escolar.', 110),
  ('L.A.C6.G3.b', 'Lenguajes', 'Artes', 'L.A.C6', 'Elementos de las artes y recursos estéticos apreciados en el entorno natural y social, así como en diversas manifestaciones artísticas.', 3, 'Interviene el entorno natural y social, mediante el uso de los lenguajes artísticos, para expresar un mensaje a favor del cuidado del medio ambiente.', 111),
  ('L.A.C7.G1', 'Lenguajes', 'Artes', 'L.A.C7', 'Valor estético de la naturaleza, de la vida cotidiana y de diferentes manifestaciones culturales y artísticas.', 1, 'Disfruta de manifestaciones culturales y artísticas de la comunidad y de otros lugares, para reconocer sus gustos e intereses estéticos.', 112),
  ('L.A.C7.G2', 'Lenguajes', 'Artes', 'L.A.C7', 'Valor estético de la naturaleza, de la vida cotidiana y de diferentes manifestaciones culturales y artísticas.', 2, 'Investiga diversas manifestaciones culturales y artísticas para expresar un juicio estético y lo difunde en la comunidad escolar.', 113),
  ('L.A.C7.G3', 'Lenguajes', 'Artes', 'L.A.C7', 'Valor estético de la naturaleza, de la vida cotidiana y de diferentes manifestaciones culturales y artísticas.', 3, 'Identifica algunas categorías estéticas como lo bello, lo sublime, lo grotesco, lo trágico, lo cómico y lo siniestro, al apreciarlas en manifestaciones culturales y artísticas, para argumentar sus juicios estéticos y difundirlos en la comunidad.', 114),
  ('L.A.C7.G1.b', 'Lenguajes', 'Artes', 'L.A.C7', 'Valor estético de la naturaleza, de la vida cotidiana y de diferentes manifestaciones culturales y artísticas.', 1, 'Disfruta los valores estéticos presentes en la naturaleza para apreciarla y expresarla.', 115),
  ('L.A.C7.G2.b', 'Lenguajes', 'Artes', 'L.A.C7', 'Valor estético de la naturaleza, de la vida cotidiana y de diferentes manifestaciones culturales y artísticas.', 2, 'Emite un juicio estético sobre un episodio significativo de la vida cotidiana y lo difunde en la comunidad escolar.', 116),
  ('L.A.C7.G3.b', 'Lenguajes', 'Artes', 'L.A.C7', 'Valor estético de la naturaleza, de la vida cotidiana y de diferentes manifestaciones culturales y artísticas.', 3, 'Identifica algunas categorías estéticas como lo bello, lo sublime, lo grotesco, lo trágico, lo cómico y lo siniestro, al apreciarlas en la naturaleza y en la vida cotidiana, para compartir sus juicios estéticos y difundirlos en la comunidad.', 117),
  ('L.A.C8.G1', 'Lenguajes', 'Artes', 'L.A.C8', 'Creaciones artísticas que tienen su origen en textos literarios.', 1, 'Explora con formas, colores, movimientos, sonidos, entre otros elementos de las artes, para reinterpretar textos literarios de la comunidad u otros lugares, haciendo uso de diversos lenguajes artísticos.', 118),
  ('L.A.C8.G2', 'Lenguajes', 'Artes', 'L.A.C8', 'Creaciones artísticas que tienen su origen en textos literarios.', 2, 'Adapta textos literarios provenientes de culturas indígenas o afrodescendientes, experimentando con elementos de las artes y recursos estéticos como la repetición, ritmo, armonía, contraste y variación, para sensibilizar a la comunidad sobre las formas de expresión de los pueblos originarios.', 119),
  ('L.A.C8.G3', 'Lenguajes', 'Artes', 'L.A.C8', 'Creaciones artísticas que tienen su origen en textos literarios.', 3, 'Construye una narrativa personal o colectiva, a partir de un texto literario de su interés, empleando en forma artística cuerpo, espacio y tiempo.', 120),
  ('L.A.C9.G1', 'Lenguajes', 'Artes', 'L.A.C9', 'Expresión artística de sensaciones, emociones, sentimientos e ideas, a partir de experiencias familiares, escolares o comunitarias.', 1, 'Recrea lúdicamente sensaciones, emociones, sentimientos e ideas, mediante el uso del cuerpo, del espacio y del tiempo, para expresar la relación con su entorno familiar.', 121),
  ('L.A.C9.G2', 'Lenguajes', 'Artes', 'L.A.C9', 'Expresión artística de sensaciones, emociones, sentimientos e ideas, a partir de experiencias familiares, escolares o comunitarias.', 2, 'Explora con técnicas artísticas y elige una para apreciar, simbolizar y compartir sensaciones, emociones, sentimientos e ideas relacionados con el entorno escolar.', 122),
  ('L.A.C9.G3', 'Lenguajes', 'Artes', 'L.A.C9', 'Expresión artística de sensaciones, emociones, sentimientos e ideas, a partir de experiencias familiares, escolares o comunitarias.', 3, 'Usa intencionalmente características y funciones de algunos géneros artísticos, para crear una obra original que simbolice sus vínculos con la comunidad.', 123),
  ('L.A.C10.G1', 'Lenguajes', 'Artes', 'L.A.C10', 'Memoria colectiva representada por medios artísticos, para registrar experiencias comunitarias.', 1, 'Recupera de la memoria colectiva acontecimientos significativos de las familias, escuelas o comunidad, para representarlos de manera creativa.', 124),
  ('L.A.C10.G2', 'Lenguajes', 'Artes', 'L.A.C10', 'Memoria colectiva representada por medios artísticos, para registrar experiencias comunitarias.', 2, 'Reinterpreta, mediante características de algunos géneros artísticos, un acontecimiento familiar, escolar o comunitario significativo de la memoria colectiva.', 125),
  ('L.A.C10.G3', 'Lenguajes', 'Artes', 'L.A.C10', 'Memoria colectiva representada por medios artísticos, para registrar experiencias comunitarias.', 3, 'Manifiesta una postura crítica sobre la memoria colectiva, acerca de un acontecimiento relevante para la comundiad, al hacer uso de los lenguajes artísticos.', 126),
  ('L.A.C11.G1', 'Lenguajes', 'Artes', 'L.A.C11', 'Procesos creativos que ponen en práctica la comunicación dialógica, como estrategia para erradicar expresiones de violencia.', 1, 'Expresa, mediante elementos de las artes como las formas, colores, movimientos y sonidos, la relevancia del diálogo como una alternativa a las manifestaciones de violencia presentes en la familia, escuela y comunidad.', 127),
  ('L.A.C11.G2', 'Lenguajes', 'Artes', 'L.A.C11', 'Procesos creativos que ponen en práctica la comunicación dialógica, como estrategia para erradicar expresiones de violencia.', 2, 'Imagina y comparte propuestas artísticas de acción para contribuir en la erradicación de la violencia en la familia, escuela y comunidad, haciendo uso de una comunicación abierta, respetuosa y empática con la diversidad.', 128),
  ('L.A.C11.G3', 'Lenguajes', 'Artes', 'L.A.C11', 'Procesos creativos que ponen en práctica la comunicación dialógica, como estrategia para erradicar expresiones de violencia.', 3, 'Presenta al público una propuesta artística respetiosa y empática con la diversidad, a. fin de sensibilizar a la comunidad acerca de la importancia del diálogo para erradicar la violencia en el entorno.', 129),
  ('L.A.C12.G1', 'Lenguajes', 'Artes', 'L.A.C12', 'Vida saludable expresada a través de mensajes construidos con elementos de las artes, para difundirlos por distintos medios de comunicación.', 1, 'Emplea intecnionalmente formas, colores, movimientos, sonidos, entre otros elementos de las artes, para representar una vida saludable y la difunde por un medio de comunicación', 130),
  ('L.A.C12.G2', 'Lenguajes', 'Artes', 'L.A.C12', 'Vida saludable expresada a través de mensajes construidos con elementos de las artes, para difundirlos por distintos medios de comunicación.', 2, 'Crea mensajes que promuevan una vida saludable, utilizando artísticamente formas, colores, movimientos y sonidos, entre otros elementos de las artes, para difundirlos por distintos medios de comunicación.', 131),
  ('L.A.C12.G3', 'Lenguajes', 'Artes', 'L.A.C12', 'Vida saludable expresada a través de mensajes construidos con elementos de las artes, para difundirlos por distintos medios de comunicación.', 3, 'Construye una narrativa a favor de una vida saludable, mediante el uso artístico de distintos formatos como fotografía, historieta, secuencia corporal, secuencia sonora, entre otros, y la difunde por distintos medios de comunicación.', 132),
  ('L.A.C13.G1', 'Lenguajes', 'Artes', 'L.A.C13', 'Sistemas alternativos y aumentativos de comunicación como herramientas creativas que favorecen la inclusión.', 1, 'Identifica algunas características sensoriales de la Lengua de Señas Mexicana, el código Braille, los tableros de comunicación y otros sistemas alternativos y aumentativos, para fomentar la interacción, sensibilización y empatía con la diversidad.', 133),
  ('L.A.C13.G2', 'Lenguajes', 'Artes', 'L.A.C13', 'Sistemas alternativos y aumentativos de comunicación como herramientas creativas que favorecen la inclusión.', 2, 'Experimenta con sistemas alternativos y aumentativos de comunicación al usar artísticamente el cuerpo, espacio, tiempo, entre otros elementos de las artes, en una propuesta comunitaria que visibilice la diversidad y fomente la inclusión social.', 134),
  ('L.A.C13.G3', 'Lenguajes', 'Artes', 'L.A.C13', 'Sistemas alternativos y aumentativos de comunicación como herramientas creativas que favorecen la inclusión.', 3, 'Crea códigos que favorezcan la inclusión, a través del uso artístico de formas, colores, texturas, movimientos, gestos, sonidos, entre otros recursos que incorporen características de los sistemas alternativos y aumentativos.', 135),
  ('L.A.C14.G1', 'Lenguajes', 'Artes', 'L.A.C14', 'Manifestaciones artísticas que emplean sistemas alternativos y aumentativos de comunicación, elaboradas por personas en condición de discapacidad y/o diseñadas para ellas.', 1, 'Reconoce los valores estéticos y creativos de las manifestaciones artísticas realizadas por personas con alguna discapacidad, para fomentar la inclusión.', 136),
  ('L.A.C14.G2', 'Lenguajes', 'Artes', 'L.A.C14', 'Manifestaciones artísticas que emplean sistemas alternativos y aumentativos de comunicación, elaboradas por personas en condición de discapacidad y/o diseñadas para ellas.', 2, 'Aprecia y reflexiona acerca del uso de sistemas alternativos y aumentativos en manifestaciones artísticas diseñadas para personas en condición de discapacidad, a fin de favorecer el tránsito a una sociedad incluyente.', 137),
  ('L.A.C14.G3', 'Lenguajes', 'Artes', 'L.A.C14', 'Manifestaciones artísticas que emplean sistemas alternativos y aumentativos de comunicación, elaboradas por personas en condición de discapacidad y/o diseñadas para ellas.', 3, 'Presenta una creación artística en la que experimente con sistemas alternativos de comunicación, para favorecer el tránsito a una sociedad incluyente.', 138),
  ('S.M.C1.G1', 'Saberes y pensamiento científico', 'Matemáticas', 'S.M.C1', 'Expresión de fracciones como decimales y decimales como fracciones.', 1, 'Usa diversas estrategias al convertir números fraccionarios a decimales y viceversa.', 139),
  ('S.M.C2.G1', 'Saberes y pensamiento científico', 'Matemáticas', 'S.M.C2', 'Extensión de los números a positivos y negativos y su orden.', 1, 'Reconoce la necesidad de los números negativos a partir de usar cantidades que tienen al cero como referencia.', 140),
  ('S.M.C2.G1.b', 'Saberes y pensamiento científico', 'Matemáticas', 'S.M.C2', 'Extensión de los números a positivos y negativos y su orden.', 1, 'Compara y ordena números con signo (enteros, fracciones y decimales) en la recta numérica y analiza en qué casos se cumple la propiedad de densidad.', 141),
